        return float(value)

    def _validate_positive_number(self, value, name, allow_zero=False):
        # Reject bools explicitly because bool is subclass of int
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError(f"{name} must be a numeric value, got {type(value)}")
