        Args:
            key (str): Unique identifier for the bucket (tenant‑isolated).
            capacity (int|float): Maximum token count; must be > 0.
            refill_rate (int|float): Tokens added per second; must be >= 0.
            now (int|float, optional): Current Unix time. If omitted, time.time() is used.
        """
        if not isinstance(key, str) or not key:
            raise ValueError("key must be a non‑empty string")
