    def consume(self, key, tokens=1, now=None):
        """Attempt to consume *tokens* from the bucket identified by *key*.

        Returns a tuple ``(allowed, remaining, wait_seconds)`` where:
            - allowed (bool): ``True`` if the request succeeded.
            - remaining (float): Tokens left after the operation (or current tokens if denied).
            - wait_seconds (float): 0 on success; otherwise the time until enough tokens are available.
        """
